tool_input.command:
python - <<'PY'
import json,glob,os
base='/workspaces/semio/semio/assets/semio'
files=sorted(glob.glob(base+'/*.kit.semio.json'))
for fp in files:
    try:
        with open(fp) as f:
            kit=json.load(f)
    except Exception:
        continue
    types=kit.get('types') or []
    ports=kit.get('ports') or []
    port_name={p.get('guid'):p.get('name') for p in ports if p.get('guid')}
    mapping={}
    for t in types:
        tname=t.get('name') or t.get('guid') or '<unknown-type>'
        for c in (t.get('connectors') or []):
            pref=c.get('port') if isinstance(c.get('port'),dict) else None
            pg=pref.get('guid') if pref else None
            if not pg: continue
            mapping.setdefault(pg,set()).add(tname)
    if not mapping:
        continue
    print('\nFILE:',os.path.basename(fp))
    for pg in sorted(mapping):
        n=port_name.get(pg,'<unnamed-port>')
        print(f'- {n} ({pg}) -> ' + ', '.join(sorted(mapping[pg])))
PY

